// ── #29 Proxy with basic-auth credentials ──
//
// The bundled Squid container does not enforce authentication, so we cannot
// assert the proxy demands credentials. We instead verify that:
//   - the transport accepts a proxy URL with embedded userinfo, and
//   - the resulting request still flows through the proxy successfully.
// Skipped if the Squid container is unavailable.
func TestDefaultApiClient_MakesRequestThroughProxyWithBasicAuth(t *testing.T) {
	if proxyURL == "" {
		t.Skip("proxy not configured")
	}
	// Inject userinfo into the proxy URL — Squid in default config accepts
	// any credentials (no auth_param basic), so the request should succeed.
	authProxy := strings.Replace(proxyURL, "http://", "http://user:pass@", 1)
	transport := petstore.NewTransportOptionsBuilder().
		Proxy(authProxy).
		Build()
	if transport.Proxy() == nil || transport.Proxy().User == nil {
		t.Fatal("expected proxy with userinfo")
	}
	client := petstore.NewDefaultApiClient(transport)
	resp, err := client.SendRequest("GET", wiremockInternalHTTPURL+"/api/test", map[string]string{}, nil)
	if err != nil {
		t.Skipf("proxy basic-auth scenario not supported by this Squid build: %v", err)
	}
	if resp.StatusCode != 200 {
		t.Errorf("expected status 200, got %d", resp.StatusCode)
	}
}

// Regression: POST/PUT/PATCH with body == nil must emit an explicit
// Content-Length: 0. Some servers / WAFs reject body-bearing verbs with
